// ============================================================ save / load
function serialize(){const o=W;W=LW;syncPlayer();W=o;if(NET.host)netSyncPilots();const c=JSON.parse(JSON.stringify(S));for(const w of Object.values(WORLDS))for(const e of w.ents)if(e.role==='frigate'&&e.tok&&isCar(e.tok)){const ct=(c.frigates||[]).find(x=>x.id===e.tok.id);if(ct)ct.wing=carWingNow(e,w)}
  for(const w of Object.values(WORLDS)){for(const e of w.ents)if(e.npc){const h=holderIn(c,e.home)||c.econ.stock[e.side];inv.addAll(h,e.load);inv.addAll(h,e.cargo)}for(const m of w.missiles){const v=invVec(m.inv),d=c.sectors[w.sid].debris;for(const k of RAWS)d[k]+=v[k]}}for(const ev of c.events)if(ev.stage==='engaged'){ev.stage='inbound';ev.eta=c.T+3}return c}
function save(){if(!S||NET.on||S.training)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(serialize()))}catch(e){}}
function loadSave(){try{const t=localStorage.getItem(SAVE_KEY);if(!t)return null;const o=JSON.parse(t);return o&&o.v===2&&o.player?o:null}catch(e){return null}}
function startWith(state){
  migrate(state);if(S.vbPend){S.vbPend=0;if(!S.training&&!NET.cl){const lg=loadLegacy(),vb=lg.vb;if(vb){delete lg.vb;try{localStorage.setItem('driftgate.legacy',JSON.stringify(lg))}catch(e){}devLedger(()=>{S.player.credits+=vb.cr||0;inv.addAll(S.player.vault,vb.items||{})});
    feed(`★★ Victory bonus from the last galaxy${vb.side&&DOCTRINE[vb.side]?` (for serving the ${DOCTRINE[vb.side].name})`:''}: +${fmt(vb.cr||0)} cr, and ${Object.entries(vb.items||{}).map(([i,c])=>c+' '+ITEMS[i].name).join(', ')} in your vault.`,'good')}}}
  if(S.player.rack===undefined)S.player.rack=0;if(!S.player.wpn)S.player.wpn='kinetic';running=true;$('start').hidden=true;$('hud').hidden=false;showTouch();
  enterSector(S.player.sector);
  if(S.player.docked==='turret')S.player.docked=null;
  if(S.player.docked==='bridge'){const F=W.ents.find(e=>e.role==='frigate'&&e.tok&&fMine(e.tok));S.player.docked=null;if(F)enterBridge(F)}
  else if(S.player.docked){const E=S.player.docked==='station'?W.stationEnt:W.outpostEnt;if(!E||(E.type==='outpost'&&!canDock(E)))S.player.docked=null;else openDock()}
  hudUpdate();
}

// ============================================================ start screen
let selFac='halcyon',selCls='interceptor';
const ROLES={combat:{name:'Combat',desc:'Fight for outposts and stations, escort convoys, hunt the Brood.',ships:['interceptor','striker','heavy','bomber']},
  mining:{name:'Mining',desc:'Strip asteroids, sell ore and fabricate parts. Guard drones keep you company.',ships:['skiff','prospector','dredger']},
  hauling:{name:'Hauling',desc:'Big holds for trade runs and supply contracts. Guard drones ride along.',ships:['courier','freighter','bulker']},
  scouting:{name:'Scouting',desc:'The fastest hulls, slow to turn. Flip sector beacons for your faction: each scans its sector for your side and pays you while it holds. Plant limpets on enemy capital ships and stations so your side hits them harder, and earn a bonus when a marked capital dies.',ships:['scout','scout2']}};
function launchCls(){if(selFac==='pirate')return'raider';return START_HULLS.includes(selCls)&&ROLES[selRole].ships.includes(selCls)?selCls:ROLES[selRole].ships.find(k=>START_HULLS.includes(k))}
let selRole='combat';
function roleOf(cls){for(const r in ROLES)if(ROLES[r].ships.includes(cls))return r;return'combat'}
function shipCard(){const C=CLASSES[selCls],st=shipStats(selFac,selCls,1),all=CLS_IDS.map(k=>shipStats(selFac,k,1)),mx=f=>Math.max(...all.map(f));
  const bars=[['Speed',x=>x.maxSpd],['Agility',x=>x.turn],['Armour',x=>x.hull],['Shields',x=>x.sCap],['Firepower',x=>x.dmg],['Hold',x=>x.cargo]].map(([l,f])=>`<div class="sbar"><span>${l}</span><div><i style="width:${Math.round(f(st)/mx(f)*100)}%"></i></div></div>`).join('');
  const extra='';const r=HULL_COST[selCls]||{},lock=!START_HULLS.includes(selCls);
  $('shipcard').innerHTML=`<canvas data-prev="${selFac}" data-big="1"></canvas><div><div class="sn2" style="color:${FAC(selFac).col}">${esc(FAC(selFac).hulls[selCls])}</div><div class="sc">${C.name}</div><div class="sd">${esc(C.desc)}${extra?' '+extra:''}</div>${bars}${lock?`<div class="sd" style="margin:8px 0 0;color:var(--amber)">You start in a starter hull. Buy one of these later at a core station Shipyard for ${fmt(hullPrice(selCls))} cr each; lose it and you're back in a starter.</div>`:''}</div>`;
  const start=launchCls();$('ssum').innerHTML=`<b>${esc(FAC(selFac).name)}</b> · ${ROLES[selRole].name} · you launch in a <b>${esc(FAC(selFac).hulls[start])}</b> ${CLASSES[start].name}`;{const code=($('mpCode')&&$('mpCode').value||'').trim();$('bLaunch').textContent=!NET.on&&mpSlug(code)&&mpOK()&&!$('mpBox').hidden?`Join “${code}” in a ${FAC(selFac).hulls[start]}`:`Launch in a ${FAC(selFac).hulls[start]}`}}
function showStart(){
  $('start').hidden=false;{const n=$('mpName');n.readOnly=!!NET.on;n.title=NET.on?'Your callsign is fixed while you are connected to a galaxy. Leave the galaxy to change it.':'';if(NET.on&&MP.name)n.value=MP.name}{const lg=loadLegacy();$('legacy').innerHTML=lg.last?`Last galaxy won by <b style="color:${sideCol(lg.last)}">${esc(lg.last==='brood'?'the Brood':FACTIONS[lg.last].name)}</b>: ${lg.last==='brood'?'nothing carries over from a Brood win':'they start this one with a finished capital shipyard and 40% richer stores'}. Galaxies won: ${Object.keys(lg.wins||{}).map(k=>`${sideName(k)} ${lg.wins[k]}`).join(' · ')}.`:'Win the galaxy by holding 7 systems for 20 minutes, or the most systems at the two-hour deadline (the Brood can only win by holding 7).'}$('bContinue').hidden=!loadSave()||NET.on;if(!ROLES[selRole].ships.includes(selCls))selRole=roleOf(selCls);
  $('roles').innerHTML=Object.keys(ROLES).map(r=>`<button class="role" type="button" data-role="${r}" aria-pressed="${r===selRole}"><b>${ROLES[r].name}</b><span>${ROLES[r].desc}</span></button>`).join('');
  {const crew=unbCrewGal(),fgal=unbFacGal(),ul=unbLegendOK(cleanCall($('mpName').value))&&!fgal,U=FAC('pirate');if(selFac==='pirate'&&!ul)selFac='halcyon';if(crew&&ul)selFac='pirate';$('facs').innerHTML=FAC_IDS.map(f=>{const F=FACTIONS[f];return`<button class="fac" type="button" data-fac="${f}" aria-pressed="${f===selFac}" style="--fc:${F.col}"><canvas data-prev="${f}"></canvas><div class="fn">${F.name}</div><div class="fb">${F.blurb}</div><div class="ft">${F.traitText}</div><div class="fb">Home: ${F.station}</div></button>`}).join('')+`<button class="fac" type="button" data-fac="pirate" aria-pressed="${selFac==='pirate'}" style="--fc:${U.col}${ul?'':';opacity:.55'}"><canvas data-prev="pirate"></canvas><div class="fn">${ul?'':'🔒 '}${U.name}</div><div class="fb">${U.blurb}</div><div class="ft">${ul?(crew?'An Unbound crew galaxy: everyone here flies for the pirates.':U.traitText):fgal?'This galaxy flies for the factions. Unbound crews need a galaxy of their own.':'Earn a Legend point flying for a faction to unlock the Unbound.'}</div><div class="fb">Home: ${U.station}</div></button>`}
  if(selFac==='pirate'){$('roles').innerHTML='<div class="note" style="padding:8px">Pirates don\'t work: no mining, hauling or scouting hulls. You start in a Raider; the Corsair and Plunderer are sold at the haven\'s black market.</div>'}
  $('clsrow').innerHTML=(selFac==='pirate'?UNB_HULLS:CLS_IDS).map(k=>`<button class="cls" type="button" data-cls="${k}" aria-pressed="${k===selCls}" ${selFac==='pirate'||ROLES[selRole].ships.includes(k)?'':'hidden'}><b>${FAC(selFac).hulls[k]}</b><em>${CLASSES[k].name}</em><span style="font-size:11px;color:var(--faint)">${selFac==='pirate'?(k==='raider'?'starting hull':'🔒 '+fmt(UNB_PRICE[k])+' cr at the haven'):START_HULLS.includes(k)?'starting hull':'🔒 '+fmt(hullPrice(k))+' cr'}</span></button>`).join('');
  shipCard();
  requestAnimationFrame(drawPreviews);
}
function drawPreviews(){document.querySelectorAll('canvas[data-prev]').forEach(c=>{const f=c.dataset.prev,w=c.clientWidth,h=c.clientHeight;if(!w)return;c.width=w*DPR;c.height=h*DPR;const g=c.getContext('2d');g.setTransform(DPR,0,0,DPR,0,0);g.clearRect(0,0,w,h);
  drawShip2D(g,f,selCls,w*.5,h*.52,c.dataset.big?Math.min(h*.5,w*.42):Math.min(h*.56,w*.23)*(.75+CLASSES[selCls].radius/80),false)})}
// small software renderer for the start-screen previews: real ship meshes, flat shaded, painter-sorted
// angled flight view: seen from above and behind, banked a little, nose climbing toward the upper right
const SHIP2D_Q=(()=>{const A=(x,y,z,a)=>qAxis(x,y,z,a,q0());return qMul(A(0,0,1,.15),qMul(A(1,0,0,.6),qMul(A(0,1,0,2.25),A(0,0,1,.3),q0()),q0()),q0())})();
function drawShip2D(c,fac,cls,cx,cy,s,dim){if(!G)return;const d=shipMesh(fac,cls).hull.data,q=SHIP2D_Q;
  const Ld=[.35,.55,.76],tris=[],v={x:0,y:0,z:0},n={x:0,y:0,z:0};
  for(let i=0;i<d.length;i+=30){qRot(q,d[i+3],d[i+4],d[i+5],n);if(n.z<=.02)continue;const P=[];let z=0;for(let k=0;k<3;k++){const o=i+k*10;qRot(q,d[o],d[o+1],d[o+2],v);P.push(cx+v.x*s,cy-v.y*s);z+=v.z}
    const lit=.3+.85*Math.max(0,n.x*Ld[0]+n.y*Ld[1]+n.z*Ld[2]),em=d[i+9],f=k=>Math.min(255,Math.round(255*d[i+6+k]*(lit*(1-em)+em)*(dim?.5:1)));tris.push([z,P,`rgb(${f(0)},${f(1)},${f(2)})`])}
  tris.sort((a,b)=>a[0]-b[0]);c.lineJoin='round';c.lineWidth=.6;for(const[,P,col]of tris){c.fillStyle=col;c.strokeStyle=col;c.beginPath();c.moveTo(P[0],P[1]);c.lineTo(P[2],P[3]);c.lineTo(P[4],P[5]);c.closePath();c.fill();c.stroke()}}
$('facs').addEventListener('click',e=>{const b=e.target.closest('[data-fac]');if(!b)return;if(b.dataset.fac==='pirate'&&(!unbLegendOK(cleanCall($('mpName').value))||unbFacGal())){$('ssum').innerHTML=`<b style="color:var(--amber)">${unbFacGal()?'This galaxy flies for the factions: Unbound crews need a galaxy of their own.':'The Unbound unlock once this callsign has earned a Legend point flying for a faction.'}</b>`;return}if(b.dataset.fac!=='pirate'&&unbCrewGal()){$('ssum').innerHTML='<b style="color:var(--amber)">This is an Unbound crew galaxy: everyone here flies for the pirates.</b>';return}selFac=b.dataset.fac;if(selFac==='pirate')selCls='raider';else if(UNB_HULLS.includes(selCls))selCls='interceptor';showStart()});
$('clsrow').addEventListener('click',e=>{const b=e.target.closest('[data-cls]');if(!b)return;selCls=b.dataset.cls;selRole=roleOf(selCls);showStart()});
$('roles').addEventListener('click',e=>{const b=e.target.closest('[data-role]');if(!b)return;selRole=b.dataset.role;if(!ROLES[selRole].ships.includes(selCls))selCls=ROLES[selRole].ships[0];showStart()});
$('bSnd').addEventListener('click',e=>{auInit();sndPanel($('sndPop').hidden)});
function sndPanel(open){const P=$('sndPop');P.hidden=!open;$('bSnd').setAttribute('aria-expanded',String(open));if(open)sndSync();else if(P.contains(document.activeElement))document.activeElement.blur()}
function sndSync(){$('sfxOn').checked=AU.on.sfx;$('musOn').checked=AU.on.music;$('sfxVol').value=AU.on.svol;$('musVol').value=AU.on.mvol;$('sfxVolV').textContent=AU.on.svol+'%';$('musVolV').textContent=AU.on.mvol+'%'}
$('sfxOn').addEventListener('change',e=>{AU.on.sfx=e.target.checked;if(!AU.on.sfx)AU.on.music=false;auSave();auApply();sndSync();e.target.blur()});
$('musOn').addEventListener('change',e=>{AU.on.music=e.target.checked;if(AU.on.music)AU.on.sfx=true;auSave();auApply();sndSync();e.target.blur()});
for(const[id,k]of[['sfxVol','svol'],['musVol','mvol']]){const el=$(id);el.addEventListener('input',()=>{AU.on[k]=+el.value;auApply();sndSync()});el.addEventListener('change',()=>{auSave();el.blur()})}
addEventListener('pointerdown',e=>{const P=$('sndPop');if(!P.hidden&&!P.contains(e.target)&&e.target!==$('bSnd')&&!$('bSnd').contains(e.target))sndPanel(false)});addEventListener('pointerdown',()=>{if(running)auInit()});
$('bNext').addEventListener('click',()=>{if(NET.host){mpNewGalaxy();return}if(NET.cl){$('win').hidden=true;flash('Waiting for the host to start the next galaxy.');return}$('win').hidden=true;if(W)exitSector();W=null;S=null;running=false;$('hud').hidden=true;$('dock').hidden=true;buildSectorScene(null);showStart()});
// ============================================================ Legendary status: points for galaxy wins, 10 levels, permanent perks
// A pilot earns 1 Legend point when their faction wins a galaxy they flew for (30+ minutes of game time, most of their time
// that galaxy). Records live on this device, keyed by callsign. In multiplayer the host decides who earned a point and tells
// each pilot's device. Perks are permanent but small; anything a perk adds at the start of a galaxy is added before that
// galaxy's ledger baseline, and every pay bonus comes out of a faction treasury.
const LEG_KEY='driftgate.legend',LEG_MIN=1800,LEG_LV=[1,2,4,6,9,12,16,20,25,30],
  LEG_TITLES=['Pathfinder','Freighter','Prospector','Veteran','Heroic Pilot','Ace','Commander','Paragon','Champion','Legendary Ace'],
  LEG_PERKS=['Scout’s instinct: in a Scout or Advanced Scout, beacons flip in 7 s instead of 10, and beacon bounties pay 20% more.',
    'Freight licence: hauler hulls get 10% more hold, the full-hold handling penalty is cut by a third, and hauling Orders pay 10% more.',
    'Miner’s eye: blast charges reach 400 m instead of 300 m, and the on-point window is 2 m wider.',
    'Your own ship: start each galaxy in the hull you finished the last one in (not capital ships), with your own ship name and engine colour.',
    'Head start: one system of your choice starts every galaxy at Mk II, with a variant of your choice fitted free.',
    'Second head start: a second system starts at Mk II, with a second free variant.',
    'Command rank: campaign bonuses pay 15% more, and your comms constructor leaves with 1 escort instead of 2.',
    'Reserve hull: a second hull waits in your Hangar each galaxy, and your faction’s next carrier is named after you.',
    'Contractor: a flat 150 cr from your faction for every Order, campaign move or beacon mission you complete.',
    'Legendary Ace: gold callsign, and the Wraith stealth fighter at any core station Shipyard.'],
  LEG_HAUL=new Set(['courier','freighter','bulker']),LEG_MINE=new Set(['skiff','prospector','dredger']),LEG_CAPITAL=new Set(['frigate','escort','carrier','constructor']),
  LEG_TRAILS=['#f0b24a','#4fd8d0','#ff7a3d','#b893ff','#7ad9a7','#ff5d8f','#ffffff','#5aa8ff'];
function legLoad(){try{const d=JSON.parse(localStorage.getItem(LEG_KEY));if(d&&d.recs)return d}catch(e){}return{recs:{}}}
function legSave(d){try{localStorage.setItem(LEG_KEY,JSON.stringify(d))}catch(e){}}
function legKey(n){return cleanCall(n||'').toLowerCase()}
function legRec(name,d){d=d||legLoad();const k=legKey(name);if(!k)return null;return d.recs[k]||(d.recs[k]={name:cleanCall(name),pts:0,wins:{},last:null})}
function legPeek(name){const k=legKey(name);return k?legLoad().recs[k]||null:null}
function legLevel(pts){let l=0;for(let i=0;i<LEG_LV.length;i++)if((pts||0)>=LEG_LV[i])l=i+1;return l}
function legTag(l){return l>=10?'Legendary Ace':l>=7?'Legend':l>=3?'Heroic Pilot':''}
function lvlOf(k){if(!S||S.training)return 0;const P=isMe(k)?S.player:(S.pilots&&S.pilots[k]);return(P&&P.lvl)||0}
function pilotLabel(P){if(!P)return'';const t=legTag(P.lvl||0);return P.name+(t?` (${t})`:'')+(P.shipName?` · ${P.shipName}`:'')}
// what a pilot's device sends the host (and what single player uses directly) to set up its perks for a new galaxy
function legPack(name){const r=legPeek(name);if(!r)return{lvl:0,pts:0};const lvl=legLevel(r.pts);return{lvl,pts:r.pts||0,mk2:r.mk2||[],fv:r.fv||[],keep:r.keep!==false,lastCls:r.lastCls||null,reserve:r.reserve||'striker',shipName:lvl>=4?(r.shipName||''):'',trail:lvl>=4?(r.trail||''):''}}
function legValidCls(c,lvl){return!!c&&!!CLASSES[c]&&!LEG_CAPITAL.has(c)&&(YARD_IDS.includes(c)||(c==='wraith'&&lvl>=10))}
// call before the galaxy's (or pilot's) ledger baseline is taken
function legendStart(P,pk){pk=pk||{lvl:0};const lvl=Math.max(0,Math.min(10,pk.lvl|0));P.lvl=lvl;P.tune=P.tune||{};P.tune.lv=lvl;if(!lvl)return;
  if(lvl>=4){P.shipName=String(pk.shipName||'').slice(0,20);P.trail=/^#[0-9a-f]{6}$/i.test(pk.trail||'')?pk.trail:'';
    if(pk.keep&&legValidCls(pk.lastCls,lvl)&&pk.lastCls!==P.cls){const c=pk.lastCls;P.cls=c;P.rack=rackCapC(c,P.tiers.weapon);P.swarm=CLASSES[c].swarm||0;P.bay={drone:CLASSES[c].drones||0}}}
  const picks=[];for(const s of(pk.mk2||[]))if(SLOT[s]&&!picks.includes(s))picks.push(s);for(const s of['shield','weapon','engine'])if(picks.length<2&&!picks.includes(s))picks.push(s);
  if(lvl>=5)P.tiers[picks[0]]=Math.max(2,P.tiers[picks[0]]||1);if(lvl>=6)P.tiers[picks[1]]=Math.max(2,P.tiers[picks[1]]||1);for(let i=0;i<2;i++){const id=(pk.fv||[])[i],V=id&&VARIANTS[id];if(lvl>=5+i&&V&&V.slot===picks[i]){P.tune=P.tune||{};P.tune.vr=P.tune.vr||{};P.tune.vr[V.slot]=id}}
  if(lvl>=5)P.rack=pRack(P);
  if(lvl>=8){const c=['striker','prospector'].includes(pk.reserve)?pk.reserve:'striker';P.ships=P.ships||[];if(P.ships.length<BAY_MAX)P.ships.push({cls:c,tiers:baseTiers(),tune:{lv:lvl},bay:{},rack:rackCapC(c,1),swarm:CLASSES[c].swarm||0,hullInv:{},stored:0});
    S.legFrig=S.legFrig||{};(S.legFrig[P.faction]=S.legFrig[P.faction]||[]).push(P.name)}}
function applyLegend(B,cls,U){const lv=(U&&typeof U==='object'&&U.lv)||0;if(lv>=2&&LEG_HAUL.has(cls)){B.cargo=Math.round(B.cargo*1.1);B.ladenK=2/3}if(lv>=3&&LEG_MINE.has(cls))B.drill*=1.1;return B}
function legMineR(P){return P&&(P.lvl||0)>=3&&LEG_MINE.has(P.cls)?400:300}
function legBonus(k,f,what,fr){if(lvlOf(k)<9||!FAC_IDS.includes(f))return 0;const amt=Math.round(150*(fr==null?1:Math.min(1,fr)));if(amt<1)return 0;const got=payKey(k,f,amt);if(got)keyFeed(k,`★ Contractor bonus for ${what}: +${fmt(got)} cr.`,'good');return got}
// time flown under each faction this galaxy (host / single player)
function legFlownTick(dt){if(!S||S.training||NET.cl)return;S.flown=S.flown||{};for(const P of allPilots()){if(!P||!P.faction)continue;const k=P.pid||'me',o=S.flown[k]||(S.flown[k]={});o[P.faction]=(o[P.faction]||0)+dt}}
function legEarned(k,side){const o=(S.flown||{})[k]||{};let best=null,bt=-1;for(const f in o)if(o[f]>bt){bt=o[f];best=f}return best===side&&(o[side]||0)>=LEG_MIN}
// galaxy over: host / single player decides; each device records its own pilot
// the faction a pilot served (flew for longest, at least LEG_MIN): a loss with it still earns half a point
function legServed(k){const o=(S.flown||{})[k]||{};let best=null,bt=-1;for(const f in o)if(o[f]>bt){bt=o[f];best=f}return best&&o[best]>=LEG_MIN&&FAC_IDS.includes(best)?best:null}
function legAward(side){if(!S||S.training||NET.cl)return;if(S.unb){unbLegend(side);return}for(const P of allPilots()){if(!P||!P.name)continue;const k=P.pid||'me',ok=FAC_IDS.includes(side)&&legEarned(k,side),sv=legServed(k),lost=!ok&&!!side&&side!=='brood'&&!!sv&&sv!==side?sv:null,vb=vicServed(k,side);
    if(!NET.on||isMe(k)){legGrant(P.name,side,ok,P.cls,lost);if(vb)vicBank(side)}else{const c=readyCl().find(x=>x.pid===k);if(c)send(c.L,{t:'legend',side,ok,cls:P.cls,vb,lost})}}}
const LEG_LOSS=.5;   // a galaxy lost, after serving a faction 30+ minutes, earns half a point; a win earns one
const legFmt=x=>{x=x||0;return Number.isInteger(x)?String(x):x.toFixed(1)};
function legGrant(name,side,ok,cls,lost){const d=legLoad(),r=legRec(name,d);if(!r)return;if(cls&&!LEG_CAPITAL.has(cls))r.lastCls=cls;let line='';
  const gain=ok?1:lost?LEG_LOSS:0;
  if(gain){const l0=legLevel(r.pts);r.pts=Math.round((r.pts+gain)*10)/10;if(ok){r.wins[side]=(r.wins[side]||0)+1;r.last={side,at:Date.now()}}else{r.losses=r.losses||{};r.losses[lost]=(r.losses[lost]||0)+1}const l1=legLevel(r.pts),need=l1<10?Math.round((LEG_LV[l1]-r.pts)*10)/10:0;
    line=ok?`★ Legend point earned: ${legFmt(r.pts)} total`:`☆ Half a Legend point for serving ${FACTIONS[lost].short} through a lost galaxy: ${legFmt(r.pts)} total`;line+=`${l1?` · level ${l1} ${LEG_TITLES[l1-1]}`:''}.`;
    if(l1>l0)line+=` New perk — ${LEG_PERKS[l1-1]}`;else if(l1<10)line+=` ${legFmt(need)} more point${need===1?'':'s'} to level ${l1+1} (a win is 1, a loss ½).`}
  else if(FAC_IDS.includes(side))line='No Legend point this time: you flew for one faction less than 30 minutes.';
  legSave(d);if(line){const el=$('winL');if(el){el.textContent=line;el.hidden=false}}}
// ---- the leaderboard sheet (start screen)
function legTitle(l){return l?LEG_TITLES[l-1]:'Unranked'}
function legRows(){const d=legLoad();return Object.values(d.recs).filter(r=>r&&r.name).sort((a,b)=>(b.pts||0)-(a.pts||0)||String(a.name).localeCompare(b.name))}
function legHtml(){const me=cleanCall($('mpName').value),d=legLoad(),r=me?legPeek(me):null,lvl=r?legLevel(r.pts):0;
  let h=`<div class="h3">Leaderboard</div><p class="note" style="margin:0 0 8px">One Legend point each time your faction wins a galaxy you flew for (at least 30 minutes, and most of your time that galaxy), and half a point when it loses. Records are kept on this device.</p>`;
  const rows=legRows();h+=rows.length?`<table class="lgt"><tr><th>#</th><th>Pilot</th><th>Level</th><th>Points</th><th>Wins by faction</th><th>Last win</th></tr>${rows.map((x,i)=>{const l=legLevel(x.pts),gold=l>=10;return`<tr${legKey(x.name)===legKey(me)?' class="me"':''}><td>${i+1}</td><td style="${gold?'color:#ffd27a;font-weight:700':''}">${esc(x.name)}${legTag(l)?` <span class="lgtag">(${esc(legTag(l))})</span>`:''}</td><td>${l} · ${esc(legTitle(l))}</td><td>${legFmt(x.pts)}</td><td>${FAC_IDS.filter(f=>(x.wins||{})[f]).map(f=>`<span style="color:${FACTIONS[f].col}">${esc(FACTIONS[f].short)} ${x.wins[f]}</span>`).join(' · ')||'—'}</td><td>${x.last?esc(FACTIONS[x.last.side]?FACTIONS[x.last.side].short:x.last.side)+' · '+new Date(x.last.at).toLocaleDateString():'—'}</td></tr>`}).join('')}</table>`:'<p class="note">No galaxy wins recorded on this device yet.</p>';
  if(!me){h+=`<p class="note" style="margin-top:12px">Enter your callsign (step 1) to see your perks and settings.</p>`;return h}
  const pts=r?r.pts:0,next=lvl<10?LEG_LV[lvl]:null;
  h+=`<div class="h3" style="margin-top:16px">${esc(me)} · level ${lvl} ${esc(legTitle(lvl))}</div><p class="note" style="margin:0 0 8px">${legFmt(pts)} Legend point${pts===1?'':'s'}${next?` · ${legFmt(Math.round((next-pts)*10)/10)} more to level ${lvl+1}`:' · maximum level'}. A win earns 1 point; a loss, after serving a faction 30+ minutes, earns ½. Perks are permanent once earned.</p><div class="lgp">${LEG_PERKS.map((p,i)=>`<div class="${i<lvl?'on':''}"><b>${i+1} · ${esc(LEG_TITLES[i])}</b> <span class="note">${LEG_LV[i]} point${LEG_LV[i]>1?'s':''}</span><br>${esc(p)}</div>`).join('')}</div>`;
  const R=r||{};const sel=(id,opts,val)=>`<select data-lg="${id}">${opts.map(([v,l])=>`<option value="${v}"${v===val?' selected':''}>${esc(l)}</option>`).join('')}</select>`;
  let st='';
  if(lvl>=4)st+=`<label>Start in my last hull${R.lastCls?` (${esc(CLASSES[R.lastCls]?CLASSES[R.lastCls].name:R.lastCls)})`:''} <input type="checkbox" data-lg="keep"${R.keep!==false?' checked':''}></label><label>Ship name <input data-lg="shipName" maxlength="20" value="${esc(R.shipName||'')}" placeholder="e.g. Night Heron"></label><label>Engine colour ${sel('trail',[['','Faction colour'],...LEG_TRAILS.map(c=>[c,c])],R.trail||'')}</label>`;
  if(lvl>=5){const so=SLOTS.map(s=>[s.id,s.name]),vo=i=>{const sl=(R.mk2||[])[i]||(i?'weapon':'shield');return[['','No variant'],...(VAR_BY_SLOT[sl]||[]).map(id=>[id,VARIANTS[id].name])]};st+=`<label>Mk II system ${sel('mk0',so,(R.mk2||[])[0]||'shield')}</label><label>Free variant ${sel('fv0',vo(0),(R.fv||[])[0]||'')}</label>`;if(lvl>=6)st+=`<label>Second Mk II system ${sel('mk1',so,(R.mk2||[])[1]||'weapon')}</label><label>Second free variant ${sel('fv1',vo(1),(R.fv||[])[1]||'')}</label>`}
  if(lvl>=8)st+=`<label>Reserve hull ${sel('reserve',[['striker','Medium Fighter'],['prospector','Medium Miner']],R.reserve||'striker')}</label>`;
  if(st)h+=`<div class="h3" style="margin-top:14px">Perk settings</div><div class="lgs">${st}</div><p class="note">Settings apply from your next new galaxy.</p>`;
  h+=`<div style="margin-top:14px"><button type="button" class="btn sm" data-lgact="reset">${legResetArm?'Click again to erase '+esc(me)+'’s legend':'Reset my legend'}</button></div>`;return h}
let legResetArm=false;
function legOpen(){$('legBody').innerHTML=legHtml();$('legend').hidden=false}
function legSet(k,v){const me=cleanCall($('mpName').value);if(!me)return;const d=legLoad(),r=legRec(me,d);if(k==='keep')r.keep=!!v;else if(k==='mk0'||k==='mk1'){const i=k==='mk0'?0:1;r.mk2=r.mk2||[];r.mk2[i]=v;r.fv=r.fv||[];const V=VARIANTS[r.fv[i]];if(V&&V.slot!==v)r.fv[i]=''}else if(k==='fv0'||k==='fv1'){r.fv=r.fv||[];r.fv[k==='fv0'?0:1]=VARIANTS[v]?v:''}else if(k==='shipName')r.shipName=cleanCall(v).slice(0,20);else if(k==='trail')r.trail=v;else if(k==='reserve')r.reserve=v;legSave(d)}

$('bLegend').addEventListener('click',()=>{legResetArm=false;legOpen()});
$('legBody').addEventListener('change',e=>{const el=e.target.closest('[data-lg]');if(!el)return;legSet(el.dataset.lg,el.type==='checkbox'?el.checked:el.value);legOpen()});
$('legBody').addEventListener('click',e=>{const b=e.target.closest('[data-lgact]');if(!b)return;if(b.dataset.lgact==='reset'){if(!legResetArm){legResetArm=true;legOpen();return}const d=legLoad();delete d.recs[legKey($('mpName').value)];legSave(d);legResetArm=false;legOpen()}});
// ============================================================ training: an offline flight school that walks through each major system
// Runs in a private galaxy (never saved over your pilot). Each step watches the game for the action it teaches.
const TR_ORE=['fe','cu','ir','xc','au','nu'],trOre=()=>TR_ORE.reduce((a,k)=>a+(S.player.cargo[k]||0),0);
function trDrones(){const p=W.player;qRot(p.q,0,0,1,_f);const out=[];for(let i=0;i<3;i++){const e=makeNPC('pirate','pirate','interceptor',1,{},'stock:pirate');e.train=true;e.wpn='kinetic';
  const o=rdir();e.x=p.x+_f.x*900+o.x*220;e.y=p.y+_f.y*900+o.y*120;e.z=p.z+_f.z*900+o.z*220;e.hull=e.st.hull*.6;e.shield=e.st.sCap*.5;faceInstant(e,p.x-e.x,p.y-e.y,p.z-e.z);W.ents.push(e);out.push(e.id)}S.training.v.dr=out}
function trDroneEnts(){return W.ents.filter(e=>e.train&&e.alive)}
function trFrig(){const f=S.player.faction;let e=W.ents.find(x=>x.role==='frigate'&&x.tok&&x.side===f&&x.alive);if(!e){const t=makeCarrier(f,W.sid,{});t.train=true;e=W.ents.find(x=>x.tok===t)}
  if(e){const p=W.player;qRot(p.q,0,0,1,_f);e.x=p.x+_f.x*1800;e.y=p.y+60;e.z=p.z+_f.z*1800;e.tok.dest=e.tok.sector;W.tgt={kind:'ship',ref:e}}}
// a practice outpost for the claim step: unclaimed, kept out of S.outposts (so the war never sees it), gone after the step
function trPost(){if(W.outpostEnt&&!W.outpostEnt.o.train)return;if(W.outpostEnt)return;const fort={};for(const k of RAWS)fort[k]=0;
  const o={id:'trainpost',sector:W.sid,name:'Practice Outpost',type:'forge',owner:null,level:1,fort,stock:{},shield:0,hull:0,breached:0,cap:{side:null,p:0},train:1};const os=oStats(o);o.shield=os.sMax;o.hull=os.hMax;
  const B=W.stationEnt||W.player,p=W.player;let dx=1,dz=.6;if(p&&B!==p){dx=p.x-B.x;dz=p.z-B.z;const l=Math.hypot(dx,dz)||1;dx/=l;dz/=l}
  const e={type:'outpost',q:q0(),o,x:B.x+dx*1800,y:B.y+60,z:B.z+dz*1800,r:95,cool:0,lastHit:-99,aim:{x:0,y:0,z:1}};W.ents.push(e);W.outpostEnt=e}
function trPostGone(){const E=W&&W.outpostEnt;if(!E||!E.o.train)return;const i=W.ents.indexOf(E);if(i>=0)W.ents.splice(i,1);W.outpostEnt=null;if(W.tgt&&W.tgt.ref===E)W.tgt=null}
const trBeacons=()=>(S.player.cargo.beacon||0)+(S.player.vault.beacon||0);
// a harmless enemy escort for the limpet step: it holds still, never fires and can't be hurt, and leaves after the step
function trDummy(){const foe=FAC_IDS.find(f=>hostile(S.player.faction,f));const p=W.player;if(!foe||!p)return;let e=W.ents.find(x=>x.role==='frigate'&&x.tok&&x.tok.dummy&&x.alive);
  if(!e){const t=makeEscort(foe,W.sid,{});t.dummy=true;t.name='Training escort';e=W.ents.find(x=>x.tok===t)}if(!e)return;qRot(p.q,0,0,1,_f);e.x=p.x+_f.x*2200;e.y=p.y+80;e.z=p.z+_f.z*2200;e.vx=e.vy=e.vz=0;W.tgt={kind:'ship',ref:e};S.player.limpetUsed=false}
function trDummyGone(){for(const t of (S.frigates||[]).filter(x=>x.dummy)){S.frigates=S.frigates.filter(x=>x!==t);const e=W.ents.find(x=>x.tok===t);if(e){e.alive=false;const i=W.ents.indexOf(e);if(i>=0)W.ents.splice(i,1);if(W.tgt&&W.tgt.ref===e)W.tgt=null}}
  for(const l of W.ents.slice())if(l.role==='limpet'&&!W.ents.includes(l.lh))limpetDrop(l)}
// a harmless wrecked escort for the salvage lesson: built from materials added to the practice galaxy's books, no Brood visit
function trHull(cls,name){const P=S.player;if(P.cls===cls)return;P.cls=cls;refreshPlayerStats();feed(`Training: you are now flying a ${name}.`,'info')}
function trMiner(){const P=S.player;if(P.cls!=='skiff'){P.cls='skiff';refreshPlayerStats();P.blN=blCap(P);P.blT=0;feed('Training: you are now flying a Light Miner. Only mining ships carry a blast rig.','info')}}
function trWreck(){if(S.player.docked)undock();trMiner();const p=W.player;if(!p)return;qRot(p.q,0,0,1,_f);const foe=FAC_IDS.find(f=>hostile(S.player.faction,f))||'pirate';
  const e={type:'ship',side:foe,fac:foe,cls:'escort',st:{radius:CLASSES.escort.radius},q:qCopy(q0(),p.q),x:p.x+_f.x*700,y:p.y+40,z:p.z+_f.z*700,load:{},cargo:{},tok:{name:'Training hulk'}};
  const w=devLedger(()=>{inv.addAll(e.load,{plate:24,wire:12,coil:6,fe:40,cu:24,ir:8});return makeWreck(e)});if(w){w.broodAt=0;w.until=S.T+1800;w.name='Training hulk'}}
const trItems=()=>Object.values(S.player.cargo||{}).reduce((a,b)=>a+b,0);
const TRAIN=[
 {t:'Flight',steps:[
  {x:()=>'Welcome to flight school. This practice galaxy is private; your course has '+S.training.plan.length+' lessons. Skip any step or lesson with the buttons below.'+' You are docked at your faction’s core station. Press <kbd>'+kb('act')+'</kbd> to launch.',ok:()=>!S.player.docked},
  {x:'<kbd>'+kb('thrust')+'</kbd> thrusts, <kbd>'+kb('brake')+'</kbd> brakes and the mouse steers: the further the pointer sits from the centre ring, the harder you turn. <kbd>'+kb('rollL')+'</kbd>/<kbd>'+kb('rollR')+'</kbd> roll. Reach <b>150 m/s</b>.',ok:()=>hyp(W.player.vx,W.player.vy,W.player.vz)>150},
  {x:'Hold <kbd>'+kb('thrust')+'</kbd> and <kbd>Shift</kbd> for the afterburner: a kick of speed, then a higher top speed while held. It drains energy, and needs a little back before it lights again.',ok:()=>(keys.ShiftLeft||keys.ShiftRight)&&hyp(W.player.vx,W.player.vy,W.player.vz)>120},
  {x:'Press <kbd>'+kb('cycle')+'</kbd> until a jumpgate is targeted, then <kbd>'+kb('autopilot')+'</kbd> for autopilot. Jumpgates link each system to its neighbours.',ok:()=>apOn&&W.tgt&&W.tgt.kind==='gate'},
  {x:'Autopilot will fly you through the gate. Press <kbd>'+kb('autopilot')+'</kbd> again to take the stick back. To jump by hand, point your nose straight through a gate ring and hold steady for 5 seconds.',ok:()=>!apOn},
  {x:'Click <b>Sound</b> at the top right to open the sound panel: switches and volume sliders for effects and music. Music follows the space you’re in (each faction, freeports, Brood space, open space), and battle music cuts in when shields, yours or your target’s, start taking fire. <kbd>'+kb('sound')+'</kbd> cycles all on → muted → effects only.',ok:()=>!$('sndPop').hidden},
  {x:'Close the panel (click anywhere else, or <kbd>Esc</kbd>).',ok:()=>$('sndPop').hidden}]},
 {t:'Weapons',setup:trDrones,steps:[
  {x:'Three harmless Unbound target drones are ahead of you. Press <kbd>'+kb('tgtH')+'</kbd> to target the nearest hostile (<kbd>'+kb('cycleH')+'</kbd> cycles).',ok:()=>W.tgt&&W.tgt.kind==='ship'&&W.tgt.ref.train},
  {x:'Shoot one down. <kbd>'+kb('fire')+'</kbd> or click fires; <kbd>1</kbd> kinetic cannons, <kbd>2</kbd> lasers. Aim at the lead marker, or hold <kbd>'+kb('track')+'</kbd> to track it. Break shields first: hulls die fast after. Damage earns a share of the bounty, so you don’t need the kill shot.',ok:()=>trDroneEnts().length<3},
  {x:'Missiles: keep a target near your nose until the lock completes, then press <kbd>'+kb('msl')+'</kbd>. Missiles hit 1.8× harder once shields are down and reload on a cooldown.',setup:()=>{if(!trDroneEnts().length)trDrones()},ok:()=>W.missiles.some(m=>m.src===W.player)},
  {x:'If something locks onto you, press <kbd>'+kb('flare')+'</kbd> for flares: they spoof missiles tracking you and cost 30 energy (stop firing for a moment if the bar is low). Try it now.',ok:()=>W.flareCd>0},
  {x:'Finish the remaining drones.',ok:()=>!trDroneEnts().length},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Bounties, swarms and wings.</b> Command pays a bounty for every enemy ship destroyed, more for bigger ships, shared by damage dealt. Heavy Fighters, Bombers, Heavy Bombers, Advanced Scouts and the Wraith also carry a swarm launcher (<kbd>'+kb('swarm')+'</kbd>): eight micro-missiles, most at your target and the rest at whoever flies beside it. Shields recharge 2.5 s after the last hit. Combat ships fly in wings, and when a wing is cut down to one or two ships the survivors run for home.'}]},
 {t:'Mining and trade',setup:trMiner,steps:[
  {x:'Only mining ships carry a blast rig, so training has moved you into a <b>Light Miner</b>. Launch if you are docked (<kbd>'+kb('act')+'</kbd>), then press <kbd>'+kb('ast')+'</kbd> to target the nearest asteroid and fly to it.',ok:()=>W.tgt&&W.tgt.kind==='ast'},
  {x:'Mining is blasting. Fault-point rings show on the rock: from within 300 m, aim at one until it turns green and press <kbd>'+kb('mine')+'</kbd> to fire a charge (if the rings fade, <kbd>'+kb('ast')+'</kbd> scans again). Back off 120 m and press <kbd>'+kb('det')+'</kbd> to detonate (<kbd>'+kb('cancel')+'</kbd> cancels). Then fly into the chunks that come off (or hold <kbd>'+kb('mine')+'</kbd> by one) and scoop <b>3 ore</b>. Each charge blows off one chunk of the rock, so a full hold takes several charges. Charges on point release the most, so placement sets your pay. Every plate and coil in Driftgate was mined from a rock that already existed: nothing is created.',setup:()=>{S.training.v.ore=trOre()},ok:()=>trOre()-(S.training.v.ore||0)>=3},
  {x:'Fly back to the station (<kbd>'+kb('cycle')+'</kbd> to target it, <kbd>'+kb('autopilot')+'</kbd> for autopilot) and press <kbd>'+kb('act')+'</kbd> to dock.',ok:()=>S.player.docked==='station'},
  {x:'Open <b>Trade → Market</b> and sell your ore. Prices follow the owner’s real stores, so a glut sells cheap and a shortage pays well.',setup:()=>{S.training.v.ore=trOre();S.training.v.cr=S.player.credits},ok:()=>trOre()<S.training.v.ore&&S.player.credits>S.training.v.cr},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Ores and hulls.</b> Ferrite, cuprite, iridium and xenocrystal are common. <b>Aurorite</b> exists only in the three deep-space systems and tunes each component once: +6% to drives, holds and blast rigs, +4% to reactor, shields, guns and armour. <b>Vantium</b> lies in four contested fields, and every Capital Keel needs it. Bigger mining and hauling hulls, bought at a core Shipyard, carry bigger charge magazines, blow off bigger chunks and scoop faster, or carry bigger holds, plus <b>guard drones</b> that launch with you and defend your ship. Haulers don’t mine.'}]},
 {t:'The station',steps:[
  {x:'In flight? Dock first (<kbd>'+kb('cycle')+'</kbd> to target the station, <kbd>'+kb('autopilot')+'</kbd> for autopilot, <kbd>'+kb('act')+'</kbd> to dock). Docked, the station screen has five tabs, on keys <kbd>1</kbd>–<kbd>5</kbd>: <b>Overview</b> (what you can do here right now), <b>Trade</b> (buy, sell and store), <b>Jobs</b> (paid work), <b>Ship</b> (upgrades, refits, your hangar and the shipyard) and <b>Station</b> (fabricate parts, build works). A dot on a tab means something there you can act on. Open <b>Station</b> (<kbd>5</kbd>): Fabricate turns ore into parts.',ok:()=>!$('dock').hidden&&dockTopOf(dockTab)==='station'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Vaults.</b> Every friendly station and outpost keeps its own vault for you (<b>Trade → Vault</b>). Goods stay where you store them: to use them somewhere else, you haul them there. The galaxy map (<kbd>'+kb('map')+'</kbd>) marks every system that holds your goods.'},
  {x:'Open <b>Ship → Shipyard</b>. Starter hulls (light fighter, light miner, light hauler, scout) are free at any core station; bigger hulls are bought. Your course puts you in the right hull whenever a lesson needs one.',ok:()=>!$('dock').hidden&&dockTab==='ship'},
  {x:'Open <b>Jobs</b> (<kbd>3</kbd>): contracts and supply drives first (hauling and mining work), then your faction’s campaign move, its orders (recon, beacons, interdiction, sabotage and more), operations to join, convoy raids and escorts, and beacon bounties.',ok:()=>!$('dock').hidden&&dockTab==='jobs'}]},
 {t:'Upgrades and variants',setup:()=>{const P=S.player;devLedger(()=>{if((P.tiers.weapon||1)<2)P.tiers.weapon=2;inv.addAll(P.vault,VARIANTS.rapid.recipe)});refreshPlayerStats()},steps:[
  {x:'Each system goes from Mk I to <b>Mk III</b>: a modest, pure gain at each level. From <b>Mk II</b> a system also takes one <b>variant</b>, a part that buys a real strength with a real cost. Mk III also needs a <b>Calibration Matrix</b>, sold only at freeports. Training has raised your Weapons to Mk II and put the parts for one variant in your vault. Open <b>Ship → Systems</b>.',ok:()=>!$('dock').hidden&&dockTab==='upg'},
  {x:'Fit <b>Rapid fire</b> to your Weapons: +45% fire rate for −25% damage per shot. Swapping is free at any dock, and spares wait in your vault.',ok:()=>!!(S.player.tune&&S.player.tune.vr&&S.player.tune.vr.weapon==='rapid')},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Builds.</b> Every system has its variants: Sprint, Vector or Long-burn drives; Surge or Steady cores; Bastion, Flicker or a tuned emitter (kinetic or laser) for shields; Heavy cannons, Rapid fire or a Long barrel; Ablative plating, a Light frame or Reactive plating; Bulk or Stabilised holds; a Deep magazine, Quick-cycle rack or Smart seekers for missiles; and three Blast Rig variants for miners. Combine them: Sprint drive, Flicker and a Bulk hold make a blockade runner.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Specialists</b> guard against one enemy and fit at any Mk: five against Unbound jammers (Faraday plating, Fast-reboot reactor, Snap-back emitter, Sealed hold and Tether cutter) and six against the Brood. Each costs only 3 plate and 3 conduit to fit from Upgrades at any dock, and faction markets stock them once the Bloom or the Unbound press that faction.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Everything fitted goes down with the ship.</b> Lose it and about half your variants spill into its salvage crate, with some of its parts; the rest is gone. <b>Reading the enemy:</b> faction wings fly their own variants (Halcyon favours Bastion and Flicker; Varkesh heavy plating and cannons; Ostrova Surge or Steady cores and Rapid fire). The target panel names what an enemy has fitted, and its weakness.'}]},
 {t:'Scouts and beacons',setup:()=>{trHull('scout','Scout');const B=S.beacons&&S.beacons[W.sid];if(B&&B.owner===S.player.faction){B.owner=null;B.by=null}},steps:[
  {x:'Launch (<kbd>'+kb('act')+'</kbd>). In a Scout the beacon status line appears under the system name.',ok:()=>!S.player.docked},
  {x:'Press <kbd>'+kb('cycle')+'</kbd> until the sector beacon (◆) is targeted, then <kbd>'+kb('autopilot')+'</kbd> to fly there.',ok:()=>W.tgt&&W.tgt.kind==='beacon'},
  {x:'Hold within 250 m of the beacon for 10 seconds to flip it to your faction. A held beacon scans its system for your side, feeds its market prices to you, and pays you a bonus plus 4 cr a minute for 10 minutes after you last flip or re-secure it.',ok:()=>{const B=S.beacons[W.sid];return B&&B.owner===S.player.faction}},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Holding a beacon.</b> For <b>3 minutes</b> after a flip nobody can flip it (the ring on the map empties as the lock runs out). Then it <b>fades for 2 minutes</b>: an enemy scout can flip it, and a friendly scout can hold it again to re-secure it. If nobody does, it drops back to neutral. In a system your side holds, the local crew keeps your beacon secured; out in contested space a scout has to keep coming back.'},
  {setup:trDummy,x:()=>'<b>Limpets.</b> Your scout carries one limpet. A training escort is ahead and targeted: it won’t fire. Fly at it (<kbd>'+kb('autopilot')+'</kbd> works), and once you are within <b>600 m</b> of its hull hold <kbd>'+kb('mine')+'</kbd> for <b>2 seconds</b>. Keep flying: the count keeps while you are in range, so a fast pass plants it.',ok:()=>{const e=W.ents.find(x=>x.tok&&x.tok.dummy);return!!e&&capPinged(e.tok,S.player.faction)}},
  {ack:1,setup:trDummyGone,ok:()=>!!S.training.ack,x:()=>'<b>What a limpet does.</b> For <b>3 minutes</b> your whole side hits the target 25% harder, sees a marked capital ship on the galaxy and Strategic maps, and your side’s fighters and bombers nearby go for it. It works on carriers, escorts, stations and depots. The target’s side is warned, and their <b>fighters can shoot it off</b>; turrets and point defence can’t. You carry one: <b>dock to rearm</b>. If a capital ship dies with your limpet on it you’re paid 500 cr for a carrier, 300 for an escort.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Sensors, not omniscience.</b> You only see strikes, convoys and battles where your side has eyes: systems with a friendly station or depot (and their neighbours), friendly outposts, held beacons, and wherever a friendly scout or capital ship is (and next door). The map dims what you can’t see. Holding the Hollow Relay taps the whole network.'}]},
 {t:'Hugging a rock',steps:[
  {x:'Target an asteroid (<kbd>'+kb('ast')+'</kbd>), slow below <b>70 m/s</b> close to it and press <kbd>'+kb('act')+'</kbd> to land. Landed, you power down everything but radar, shields included: enemies beyond 320 m lose you.',ok:()=>!!W.player.landed},
  {x:'Stay landed for five seconds and watch the contacts list.',ok:()=>W.player.landed&&W.t-W.player.landed.t>5},
  {x:'Press <kbd>'+kb('act')+'</kbd> to lift off. Systems take four seconds to re-energise: no guns until they are back up, and shields recharge from empty.',ok:()=>!W.player.landed}]},
 {t:'Salvage and wrecks',setup:trWreck,steps:[
  {x:'A wrecked escort drifts ahead, its salvage points glowing. Destroyed carriers and escorts leave wrecks like this, and miners cut them apart (you’re back in a Light Miner). Press <kbd>'+kb('cycle')+'</kbd> until a salvage point is targeted and fly to it.',ok:()=>W.tgt&&W.tgt.kind==='wpt'},
  {x:'Wreck sections crack at their joint ring. Fire a charge onto it (<kbd>'+kb('mine')+'</kbd>), back off and press <kbd>'+kb('det')+'</kbd>, then scoop <b>6 units</b> from the chunk. A reactor core needs every charge on point, or the whole wreck goes up. A third of what’s inside a wreck comes out as intact components: plate, coil and conduit.',setup:()=>{S.training.v.it=trItems()},ok:()=>trItems()-(S.training.v.it||0)>=6},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Reading a wreck.</b> The reactor core holds the best of it, but it must be cracked <b>perfectly</b>: one charge near or off its joint and it blows in a 600 m blast that badly damages every ship inside and destroys the whole wreck. While core charges are set, the blast warning reaches 600 m. A wreck breaks up after <b>5 minutes</b>, and the Brood come for wrecks and eat them fast. Wrecks show on the galaxy map as an amber ✕.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Other salvage.</b> A destroyed freighter or fighter spills a crate: fly into it to scoop. Galaxy events bring <b>derelict cargo</b> (an abandoned hold, free to whoever gets there first) and <b>comets</b> (rich ore that breaks up after a few minutes), and also <b>ion storms</b> (for 2½ minutes shields don’t recharge and radar reaches only about a kilometre) and <b>gate collapses</b> (one link down for 2 minutes). Watch the feed and the map.'}]},
 {t:'Hauling for the war',steps:[
  {x:'Dock at the station (<kbd>'+kb('cycle')+'</kbd>, <kbd>'+kb('autopilot')+'</kbd>, then <kbd>'+kb('act')+'</kbd>).',ok:()=>S.player.docked==='station'},
  {x:'Open <b>Ship → Shipyard</b> and switch to the <b>Light Hauler</b>: a big hold for cargo.',ok:()=>S.player.cls==='courier'},
  {x:'Open <b>Jobs</b>: delivery contracts, supply drives and freeport requests, paid from treasuries. Faction contracts take goods you mined, salvaged or made; freeport requests take anything not bought at that freeport. Jobs come small, medium and large: a bigger hold fills a big job in fewer trips, and any job can be delivered in parts.',ok:()=>!$('dock').hidden&&dockTab==='jobs'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Front-line resupply.</b> Carriers build their own fighters from a store of plate and coil. Land on a friendly carrier’s flight deck carrying what it lacks and it unloads straight into the store, paid the market rate times a front-line bonus of up to ×2.2 when the carrier is out where the fighting is. Orders lists which carriers need what.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Blockade runs.</b> Stations that are cut off or under siege pay about four times value for goods brought in person (anything you own counts, even goods bought on a market). Carrying the cargo through hostile space nearby draws an interdiction wing that hunts you.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Convoys.</b> In a hauling ship with at least 10 t aboard, set a course on the map, then call a convoy from Orders while docked: a faction escort wing forms up on you, jumps with you, and goes home when you dock at a friendly station at the destination. Pilots who fly escort within 4 km are paid 120 cr for each jump into or out of hostile or unclaimed space.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Containment supply.</b> Stations on the border of Brood space post orders for torpedoes, missiles and plate at about two and a half times value, listed with the blockade runs. Brood swarms are what you’ll meet on the way in.'}]},
 {t:'Logistics and raiding',steps:[
  {x:'Open <b>Jobs</b>. <b>Convoy raids</b> lists enemy freighters within reach, each with a bounty: press Intercept to set a course. Under <b>Convoy escort</b> you can sign on to fly with one of your own, and Command pays when it docks.',ok:()=>!$('dock').hidden&&dockTab==='jobs'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Logistics.</b> Each faction’s core station is its warehouse and each depot keeps its own store. Freighters carry surplus ore in and components out to depots that are building and to carriers in the field. They’re real ships: a destroyed freighter spills half its hold as salvage, and losing them starves the front.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>War effort.</b> Orders delivered, supply-drive loads, campaign moves, beacon flips and enemy ships shot down all earn your faction War effort. It fades over about 20 minutes, and while it lasts your faction’s fleets fight harder in the battles fought out of sight. The Campaign section (Missions, or Orders during a supply drive) shows the current bonus.'}]},
 {t:'Comms and capital ships',setup:trFrig,steps:[
  {x:'Launch (<kbd>'+kb('act')+'</kbd>).',ok:()=>!S.player.docked},
  {x:'Press <kbd>'+kb('comms')+'</kbd> to open comms on the Command page: <kbd>1</kbd> escort me, <kbd>2</kbd> guard me, <kbd>3</kbd> call in a constructor to build here, <kbd>4</kbd> distress call. Press <kbd>'+kb('comms')+'</kbd> again to step through the friendly ships around you. <kbd>Esc</kbd> closes it.',ok:()=>commsOpen()},
  {x:'A carrier of your faction is holding just ahead (targeted). Fly to it (<kbd>'+kb('autopilot')+'</kbd>), match its speed (under 140 m/s relative), and press <kbd>'+kb('act')+'</kbd> to land on its flight deck and board.',ok:()=>!!(W.bridge)},
  {x:'You’re on the bridge, at the <b>Strategic</b> console: a live map of the system. Press <b>Take command</b> to fly this carrier (or ride along as a guest). Walk with <kbd>WASD</kbd>; <kbd>'+kb('act')+'</kbd> uses a console.',ok:()=>!!(W.bridge&&fMine(W.bridge.f.tok))},
  {x:'Open the <b>Hangar</b> tab (on an escort this is Weapons): give the carrier’s fighters wing missions, and send strikes into the next system. Bombers crack defences; assault ships capture depots and outposts, and come back if they survive.',ok:()=>!!(W.bridge&&W.bridge.panel==='wpn')},
  {x:'Open the <b>Helm</b> tab: click the map to move, and set a jump course. <b>Engineering</b> shares power between drives, shields, the flight deck and point defence.',ok:()=>!!(W.bridge&&W.bridge.panel==='nav')},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Escorts</b> are smaller capital ships: their Weapons station fires twin torpedo bays, the weapon that really hurts capital ships and stations, and point defence shoots down incoming torpedoes. Keep fighters around your capital ships to stop enemy bombers getting their torpedoes in.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Crewing together.</b> In multiplayer any pilot of your faction can board a squadmate’s carrier or escort as crew, and the commander hands each crew member one station (Helm, Weapons, called Hangar on a carrier, or Engineering) from the Strategic console. A squadmate’s Bomber or Heavy Bomber turret can be crewed too: sign on in Ship → Shipyard while docked together.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Getting capital ships.</b> A Capital Shipyard at your faction’s main station (4 Depot Frames, 4 Capital Keels, 4 Crystal Lattice, 40 plates, 2 Compact Seals, 5,000 cr) commissions one Fleet Carrier per faction (3 Seals) and its Escorts (1 Seal each). Seals are sold only at freeports. Friendly fighter wings in the system form up and screen capital ships from bombers.'},
  {x:'Step away from the console and leave by the hatch (<kbd>'+kb('act')+'</kbd>): you lift straight off the deck.',ok:()=>!W.bridge}]},
 {t:'Fighting for territory',steps:[
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Holding ground.</b> Stations, depots and outposts hold systems. Fighter guns only chip their armour: <b>bombers</b> and escort torpedoes break shields and defences, then <b>assault ships</b> (from carriers and escorts) land marines to capture them. Comms <kbd>3</kbd> calls in a constructor to build a depot where you are.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Stations and depots.</b> They carry shields and turrets that shoot down torpedoes; knock a shield down and its turrets go dark for 20 seconds. Main stations can’t be destroyed, but a depot at zero hull is captured if the attackers have assault loads there, or destroyed. Stations grow modules beside them (life support, storage, production, a defence platform, hull and shield works), and a depot can build a <b>fighter hangar</b> that scrambles fighters when hostiles come close.'},
  {x:()=>'<b>Claim Beacons</b> take outposts. Any of your faction’s stations and depots sells them for '+fmt(CLAIM_PRICE)+' cr (or fabricate one at <b>Station → Fabricate</b>). '+(S.player.docked?'':'Dock first (<kbd>'+kb('cycle')+'</kbd> to the station, <kbd>'+kb('autopilot')+'</kbd>, <kbd>'+kb('act')+'</kbd>). ')+'Open <b>Trade → Market</b> and buy one: it’s the last row.',setup:()=>{const P=S.player;S.training.v.bc=trBeacons();if(P.credits<CLAIM_PRICE)devLedger(()=>{P.credits+=CLAIM_PRICE})},ok:()=>trBeacons()>(S.training.v.bc||0)},
  {x:()=>'A beacon weighs <b>'+mass('beacon')+' t</b>, more than a fighter’s hold, so a claim takes a hauler or a big miner: training has put you in a <b>Light Hauler</b>. Purchases land in your vault and a beacon only works aboard: press <b>Load</b> on its row.',setup:()=>trHull('courier','Light Hauler'),ok:()=>(S.player.cargo.beacon||0)>0},
  {setup:trPost,x:()=>'A <b>practice outpost</b>, unclaimed, sits outside. Launch, target it (<kbd>'+kb('cycle')+'</kbd>) and fly into its ring: stay within <b>450 m</b> for about <b>12 seconds</b> to claim it. A hostile ship in the ring contests the claim, and an outpost someone holds must be breached first.',ok:()=>{const E=W.outpostEnt;return!!E&&E.o.train&&(E.o.owner==='player'||E.o.owner===S.player.faction)}},
  {ack:1,setup:trPostGone,ok:()=>!!S.training.ack,x:'<b>Outposts.</b> Claimed, an outpost is yours to fortify with parts at its dock, and it fights back with its own turrets. The three <b>Forges</b> make Crystal Lattice and Resonance Cores faster than anywhere else. The <b>Hollow Relay</b> collects gate tolls and warns of strike groups. The <b>Wrack Salvage Yard</b> harvests debris.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Fighting together.</b> When your faction runs a strike or defence, press <kbd>'+kb('op')+'</kbd> to join it. <kbd>'+kb('assist')+'</kbd> targets whoever is attacking a nearby friendly, and <kbd>'+kb('distress')+'</kbd> sends a distress call that brings your faction’s wings.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>The Brood</b> grow from The Bloom, one system at a time. Their swarms raid stations, their capital ships hunt, and they feed on wrecks. The Brood lesson covers fighting them.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Special hulls.</b> The <b>Wraith</b> (Legend level 10) cloaks with <kbd>'+kb('stealth')+'</kbd>: hidden beyond 600 m, but no guns, shields or locks until you press <kbd>'+kb('stealth')+'</kbd> again or take a hit. Both bombers carry a rear dorsal turret: an AI gunner mans it, or another pilot can board and man it while you fly.'}]},
 {t:'The Brood',steps:[
  {x:'Open the galaxy map (<kbd>'+kb('map')+'</kbd>). The Bloom sits at the top; Brood-held systems are <b>hatched</b>. A dashed ring with <b>SEEDER</b> and a countdown marks where a Seeder is heading; <b>ROOTING</b> counts down a young Bloom Node; <b>◆ FEED</b> marks a feeding ground.',ok:()=>!$('map').hidden},
  {x:'Close the map (<kbd>'+kb('map')+'</kbd>).',ok:()=>$('map').hidden},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>How it spreads.</b> A Seeder drifts to a system next to Bloom space and plants a Bloom Node, fragile for its first 3 minutes; then the node roots and the system is the Bloom’s. Every stage is a chance to stop it. <b>Containment orders</b> pay every faction pilot: 600 cr for a Seeder, 900 for a node burned before it roots, 1,500 after. A scout who keeps a Seeder targeted within 5 km for 3 s before it plants earns 250 cr.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Truce zones.</b> In every Brood-held system the factions can’t hurt each other: shots pass through rivals, and only the Brood is a target. The truce lasts 30 s after the last node burns, then the race to claim the system begins. Nothing can be built in a truce zone.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>The haze.</b> In Bloom space shields recharge 15% slower and radar reaches a quarter less. Each Brood hit leaves a spore that nibbles your hull for 4 s (up to 3; docking clears them). Brood wings go for the most damaged ship, so pull a hurt wingman out early. Brood hulls are tough and regrow, and kinetics beat lasers against them.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>An ecology.</b> What the swarms graze goes partly into each node’s <b>gut</b> (shown on its target panel) and partly into <b>feeding grounds</b> of rich rock in Brood space, which any faction can mine under the truce. Burn a node and its gut spills as big, rich rocks. Grazers carry real ore in their bellies.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>The Containment Accord.</b> Once the Brood holds 5 systems, all three factions stop fighting each other everywhere and turn on the Bloom, until it is back below 4. A Brood win consumes the galaxy and earns nobody a Legend point.'}]},
 {t:'Jammers and the Unbound',steps:[
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Jammers.</b> Unbound pirates fly Raiders, Corsairs and Plunderers. They strip your shields, then switch to jammers: a <b>Jam bar</b> fills on your screen as they hit your bare hull. Thrust stutters and guns misfire, and at a full bar your ship goes dark for 5 to 12 seconds while they hook your hold. Jammers never kill, and they can’t touch a ship with shields up.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Beating a take.</b> Keep your shields up, or break away with the afterburner while the bar drains (stop being hit for 1.5 s and it falls 10% a second). After a take your ship is hardened for a minute. Their <b>harpoons</b> fill a third of the bar and let them hook from 400 m; flares cut the line if you fit a Tether cutter. Anti-jam variants stretch the bar, reboot faster, snap shields back or seal half your hold.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Flying for the pirates.</b> With a Legend point, the <b>Unbound</b> card unlocks on the start screen. You start at Scrapheart Haven in The Wrack. <kbd>4</kbd> is jam mode (jammers and harpoons); hold <kbd>'+kb('act')+'</kbd> beside a jammed ship to hook its hold; <kbd>'+kb('stealth')+'</kbd> raises false colours, a neutral transponder that works while a faction’s heat with you is cool. Fence the loot, grow the haven’s works, and earn your Legend point with Infamy and a Deed.'}]},
 {t:'Winning the war',steps:[
  {x:'Press <kbd>'+kb('map')+'</kbd> for the galaxy map: territory, operations, beacons, wrecks, enemy capitals marked by limpets and every faction’s progress.',ok:()=>!$('map').hidden},
  {x:'A faction wins by holding <b>7 systems for 20 minutes</b>, or by holding the most systems at the <b>two-hour deadline</b>. The Brood can only win by holding 7, so stop it before it gets there. Stations, depots and outposts hold a system; the others band together against any faction that reaches 7. Close the map (<kbd>'+kb('map')+'</kbd>).',ok:()=>$('map').hidden},
  {x:'The orders card (Command panel, right) lists your faction’s campaign move and its faction orders: recon, beacon pushes, interdiction, sabotage, screening, counter-attacks, capital hunts and Brood purges, each with its pay. <kbd>Shift</kbd>+<kbd>'+kb('orders')+'</kbd> steps to the next order; <kbd>'+kb('orders')+'</kbd> signs on to the picked one and sets your course. Press <kbd>'+kb('orders')+'</kbd>.',ok:()=>!!(S.training.pk||keys.KeyP)},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>How a galaxy ends.</b> The moment a side holds 7 systems, a 20-minute clock starts (the chip at the top of the screen shows it); drop below 7 and it resets. Every pilot who helped a campaign move earns a victory bonus when their faction wins (3,000 cr plus parts, paid into your vault at the start of the next galaxy). If no one manages that within <b>two hours</b>, the side holding the most systems at the deadline wins instead (ties go to most stations, then capital ships, then the richest stores). Either way a new galaxy begins, with the winner starting 40% richer and with the parts for a capital shipyard.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>The Brood can win too.</b> If the Bloom holds 7 systems for 20 minutes, the galaxy is consumed and no pilot earns a Legend point, not even the half point for a lost galaxy. When a faction reaches 7 systems, the other powers call a truce and turn on it; against the Brood the <b>Containment Accord</b> starts earlier, at 5 Brood systems, so watch the map.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Legend points.</b> Fly most of a galaxy (at least 30 minutes) for one faction. If it wins you earn a Legend point; if it loses you still earn half a point. Points raise you through ten levels, each with a permanent perk for scouts, haulers, miners, fighters and commanders. Your record is on the start screen’s leaderboard. Your first Legend point also unlocks <b>the Unbound</b> on the start screen.'},
  {ack:1,ok:()=>!!S.training.ack,x:'<b>Playing with friends.</b> Friends can share a galaxy (it is built for up to four pilots): everyone types a callsign and the same galaxy code on the start screen. The first pilot in hosts; each picks a faction, so you can fly together or against each other. Press <kbd>Enter</kbd> in flight to message everyone. Every pilot keeps a copy of the save, so anyone can host the next session.'}]}];
function trCur(){const T=S.training,L=TRAIN[T.i];return L?{L,s:L.steps[T.j]}:null}
function trEnter(){const c=trCur();if(!c)return;const T=S.training;T.ack=0;if(T.j===0&&c.L.setup)try{c.L.setup()}catch(e){}if(c.s.setup)try{c.s.setup()}catch(e){}T.html=''}
// training comes as courses: a short core everyone flies, then the lessons for the role picked on the start screen, then how to
// win. The full course is every lesson in order. The Brood and the Unbound are also explained the first time a pilot meets them.
const TR_CORE=['Flight','Weapons','The station','Upgrades and variants'],TR_END=['Winning the war'],
  TR_TRACKS={combat:{name:'Combat',les:['Fighting for territory','Comms and capital ships','The Brood']},mining:{name:'Mining',les:['Mining and trade','Salvage and wrecks','Hugging a rock']},
    hauling:{name:'Hauling',les:['Hauling for the war','Logistics and raiding']},scouting:{name:'Scouting',les:['Scouts and beacons','Hugging a rock']}};
function trIdx(t){return TRAIN.findIndex(L=>L.t===t)}
function trPlan(track){if(track==='full')return TRAIN.map((_,i)=>i);const tr=TR_TRACKS[track]||TR_TRACKS.combat;return[...TR_CORE,...tr.les,...TR_END].map(trIdx).filter(i=>i>=0)}
function trAdvance(){const T=S.training;trDummyGone();trPostGone();T.k++;T.i=T.k<T.plan.length?T.plan[T.k]:TRAIN.length;T.j=0;trEnter()}
function trNext(){const T=S.training;T.j++;if(T.j>=TRAIN[T.i].steps.length){T.done.push(T.i);feed(`✓ Training: ${TRAIN[T.i].t} complete.`,'good');SFX.count&&SFX.count(true);trAdvance();return}trEnter()}
function trainTick(){const T=S.training;if(!T||!W||!W.player)return;const c=trCur();
  if(c){let ok=false;try{ok=c.s.ok()}catch(e){}if(ok&&W.t>=(T.cool||0)){T.cool=W.t+.6;trNext()}}
  const el=$('train');const c2=trCur();
  const h=c2?`<div class="trh"><b>Training · ${T.k+1}/${T.plan.length} · ${esc(c2.L.t)}</b><button type="button" class="trx" data-tr="min" aria-label="Collapse">${T.min?'+':'–'}</button></div>`
    +(T.min?'':`<div class="trs">${typeof c2.s.x==='function'?c2.s.x():c2.s.x}</div><div class="trp">${c2.L.steps.map((_,k)=>`<i class="${k<T.j?'d':k===T.j?'c':''}"></i>`).join('')}</div><div class="trb">${c2.s.ack?'<button type="button" class="btn sm pri" data-tr="ack">Got it</button>':'<button type="button" class="btn sm" data-tr="skip">Skip step</button>'}<button type="button" class="btn sm" data-tr="lesson">Next lesson</button><button type="button" class="btn sm" data-tr="exit">Exit</button></div>`)
   :`<div class="trh"><b>Training complete</b></div><div class="trs">${T.track==='full'?'You have flown every major system in Driftgate.':`You have finished the ${esc((TR_TRACKS[T.track]||{}).name||'')} course. The other lessons are under Training on the start screen, and the Brood and the Unbound are explained the first time you meet them.`} Keep flying this practice galaxy, or exit and launch a real pilot.</div><div class="trb"><button type="button" class="btn sm" data-tr="exit">Exit training</button></div>`;
  if(h!==T.html){T.html=h;el.innerHTML=h}el.hidden=false;{const tl=$('hTL');if(tl&&innerWidth>640){const y=Math.round(Math.max(118,tl.getBoundingClientRect().bottom+12));if(el._y!==y){el._y=y;el.style.top=y+'px'}}}}
function trainStart(track){track=track||selRole;$('trPick').hidden=true;const plan=trPlan(track),cs=cleanCall($('mpName').value)||'Cadet';auInit();auApply();FEED.length=0;newGame(selFac==='pirate'?'halcyon':selFac,'interceptor');S.player.name=cs;S.training={plan,k:0,i:plan[0],track,j:0,done:[],v:{},html:''};document.body.classList.add('trn');startWith(S);
  feed(`Welcome to flight school, ${cs}. This is a private practice galaxy: nothing here touches your saved pilot.`,'good');trEnter()}
$('train').addEventListener('click',e=>{const b=e.target.closest('[data-tr]');if(!b||!S||!S.training)return;const T=S.training,k=b.dataset.tr;
  if(k==='min'){T.min=!T.min;T.html=''}else if(k==='ack')T.ack=1;else if(k==='skip')trNext();else if(k==='lesson'){trAdvance()}else if(k==='exit')location.reload()});
// the course picker: the role chosen on the start screen is recommended; the full course is every lesson
function trPickHtml(){const n=t=>trPlan(t).length;return`<div class="trh2">Flight school</div><p>A short core for everyone (flying, weapons, the station, upgrades, how to win), then the lessons for one role. About ${n(selRole)} lessons; the full course is ${n('full')}.</p><div class="trbs">${Object.keys(TR_TRACKS).map(k=>`<button class="btn ${k===selRole?'pri':''}" type="button" data-trk="${k}">${esc(TR_TRACKS[k].name)} course · ${n(k)}</button>`).join('')}<button class="btn" type="button" data-trk="full" id="bTrainFull">Full course · ${n('full')}</button><button class="btn" type="button" data-trk="x">Cancel</button></div>`}
$('bTrain').addEventListener('click',()=>{const el=$('trPick');if(!el.hidden){el.hidden=true;return}el.innerHTML=trPickHtml();el.hidden=false});
$('trPick').addEventListener('click',e=>{const b=e.target.closest('[data-trk]');if(!b)return;const k=b.dataset.trk;if(k==='x'){$('trPick').hidden=true;return}trainStart(k)});
// first meetings: a one-time tip (per device) the first time a pilot flies into Bloom space or is jammed, pointing to the lesson
function firstTip(key,msg){if(S&&S.training)return;let seen={};try{seen=JSON.parse(localStorage.getItem('driftgate.tips')||'{}')||{}}catch(e){}if(seen[key])return;seen[key]=1;try{localStorage.setItem('driftgate.tips',JSON.stringify(seen))}catch(e){}feed(msg,'warn');flash(msg)}
function firstTips(){if(!W||!W.player||S.player.docked)return;const p=W.player;
  if(sectorOwner(W.sid)==='brood')firstTip('brood','First time in Bloom space: the factions can’t hurt each other here, shields recharge slower, and Brood hits leave spores that eat your hull. Kill Seeders and burn Bloom Nodes for bounties. Training → Combat course covers the Brood.');
  if((p.jam||0)>0)firstTip('jam','You’re being jammed: Unbound pirates fill a jam bar once your shields are down, then hook your cargo. Keep your shields up or break away with the afterburner while the bar drains.')}
$('bLaunch').addEventListener('click',()=>{const cs=cleanCall($('mpName').value);$('mpName').value=cs;if(cs.length<2){$('ssum').innerHTML='<b style="color:var(--danger)">Choose a callsign first (step 1).</b>';$('mpName').focus();return}if(!NET.on)MP.name=cs;try{localStorage.setItem('driftgate.mpname',cs)}catch(e){}
  {const code=($('mpCode').value||'').trim();if(!NET.on&&mpSlug(code)&&mpOK()&&!$('mpBox').hidden){auInit();auApply();MP.autoLaunch={fac:selFac,cls:launchCls()};mpJoin();return}}
  if(NET.on){auInit();auApply();mpLaunch(selFac,launchCls());return}auInit();auApply();FEED.length=0;newGame(selFac,launchCls(),cs);S.player.name=cs;if(selFac==='pirate'){S.unb=1;unbP();S.player.cls='raider'}startWith(S);feed(`Welcome aboard, ${cs}, ${selFac==='pirate'?'captain of the Unbound':'pilot of the '+FAC(selFac).name}. Your vault holds a few plates and conduit: check Ship → Systems for your first upgrade.`,'info');feed('Launch with E. Steer with the mouse, thrust with W. In a mining ship, R targets a rock, F fires a charge onto a fault point and '+kb('det')+' detonates; fly into the chunks to scoop them.','info');save()});
